cat > /tmp/fp_test.cpp << 'EOF'
#include <cfloat>
#include <iostream>
#include <iomanip>

int main() {
    std::cout << "FLT_EVAL_METHOD = " << FLT_EVAL_METHOD << "\n";
    std::cout << "sizeof(float)=" << sizeof(float)
              << " sizeof(double)=" << sizeof(double)
              << " sizeof(long double)=" << sizeof(long double) << "\n\n";

    float fa = 0.1f + 0.2f;
    float fb = 0.3f;
    std::cout << std::boolalpha;
    std::cout << "float:  0.1f+0.2f == 0.3f -> " << (fa == fb) << "\n";
    std::cout << std::setprecision(20);
    std::cout << "  0.1f+0.2f = " << fa << "\n";
    std::cout << "  0.3f      = " << fb << "\n\n";

    double da = 0.1 + 0.2;
    double db = 0.3;
    std::cout << "double: 0.1+0.2 == 0.3 -> " << (da == db) << "\n";
    std::cout << "  0.1+0.2 = " << da << "\n";
    std::cout << "  0.3     = " << db << "\n";
    return 0;
}
EOF
clang++ -O0 -std=c++17 /tmp/fp_test.cpp -o /tmp/fp_test && /tmp/fp_test
